import Foundation

struct EmojiEntry: Decodable, Hashable, Identifiable {
    let emoji: String?
    let name: String
    let shortcodes: [String]
    let group: String
    // github-only emoji have no unicode character, just an image
    let image: String?

    var id: String { name }

    // what the web client sends when a reaction is picked
    var shortcode: String { shortcodes.first ?? name }
}

// the github emoji set from @tiptap/extension-emoji, generated by scripts/generate-emoji.ts
enum EmojiCatalog {
    static let all: [EmojiEntry] = {
        guard
            let url = Bundle.main.url(forResource: "emoji", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let entries = try? JSONDecoder().decode([EmojiEntry].self, from: data)
        else {
            return []
        }

        return entries
    }()

    static let groups: [(name: String, emoji: [EmojiEntry])] = {
        var order: [String] = []
        var byGroup: [String: [EmojiEntry]] = [:]

        for entry in all where entry.group != "components" {
            if byGroup[entry.group] == nil {
                order.append(entry.group)
            }

            byGroup[entry.group, default: []].append(entry)
        }

        return order.map { ($0, byGroup[$0, default: []]) }
    }()

    private static let lookup: [String: EmojiEntry] = {
        var lookup: [String: EmojiEntry] = [:]

        for entry in all {
            for key in [entry.name] + entry.shortcodes + [entry.emoji].compactMap({ $0 }) where lookup[key] == nil {
                lookup[key] = entry
            }
        }

        return lookup
    }()

    // a reaction from the web client is a shortcode, one sent by a plugin can be the character itself
    static func find(_ value: String) -> EmojiEntry? {
        lookup[value]
    }
}
